    sl.addText(ins.score, {
      x: x + 0.1, y: 4.88, w: 2.8, h: 0.3,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: SLATE, align: "center", margin: 0
    });
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 8 — Key Takeaways
// ══════════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: NAVY };

  // Accent top
  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.08, fill: { color: ACCENT } });

  sl.addText("Key Takeaways", {
    x: 0.5, y: 0.3, w: 9, h: 0.65,
    fontSize: 30, fontFace: "Georgia", bold: true,
    color: WHITE, align: "left", margin: 0
  });
  sl.addText("Self-Awareness Is the Missing Piece in Agent Planning", {
    x: 0.5, y: 0.9, w: 9, h: 0.35,
    fontSize: 14, fontFace: "Calibri", italic: true,
    color: ICE, align: "left", margin: 0
  });

  const takeaways = [
    {
      num: "1",
      text: "Indiscriminate knowledge injection wastes resources — methods using 100% knowledge (KnowAgent, WKM, ExpeL) consistently underperform KnowSelf's selective approach."
    },
    {
      num: "2",
      text: "KnowSelf's three-situation taxonomy (fast / slow / knowledgeable thinking) provides a principled, human-inspired framework for agents to autonomously regulate cognitive resources."
    },
    {
      num: "3",
      text: "Llama-8B + KnowSelf achieves 84.33% on ALFWorld — surpassing GPT-4o ReAct (76.12%) and GPT-4o ExpeL (79.85%) — using only 15% knowledge."
    },
    {
      num: "4",
      text: "Special-token mechanism is lightweight: heuristic labeling on self-explored trajectories, no expensive human annotation or massive external feedback collection."
    },
    {
      num: "5",
      text: "Scales down effectively — Gemma-2B with KnowSelf reaches 79.85%, matching GPT-4o ExpeL and exceeding all other Gemma-2B baselines."
    }
  ];

  takeaways.forEach((t, i) => {
    const y = 1.38 + i * 0.82;
    // Number circle
    sl.addShape(pres.shapes.OVAL, {
      x: 0.5, y: y + 0.05, w: 0.38, h: 0.38,
      fill: { color: ACCENT }
    });
    sl.addText(t.num, {
      x: 0.5, y: y + 0.05, w: 0.38, h: 0.38,
      fontSize: 13, fontFace: "Calibri", bold: true,
      color: WHITE, align: "center", valign: "middle", margin: 0
    });
    // Text
    sl.addText(t.text, {
      x: 1.0, y: y, w: 8.5, h: 0.75,
      fontSize: 12, fontFace: "Calibri",
      color: ICE, align: "left", valign: "top", margin: 0
    });
  });

  // Footer
  sl.addText("Source: arxiv.org/abs/2504.03553  ·  KnowSelf: Agentic Knowledgeable Self-Awareness for LLM-Based Agents", {
    x: 0.5, y: 5.2, w: 9, h: 0.28,
    fontSize: 9, fontFace: "Consolas",
    color: MUTED, align: "left", margin: 0
  });
}

// ─── Write file ───────────────────────────────────────────────────────────────
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("✅  Saved: /app/output/final_deck.pptx"))
  .catch((err) => { console.error("❌ Error:", err); process.exit(1); });

