const pptxgen = require("pptxgenjs");

// ─── Palette ─────────────────────────────────────────────────────────────────
const NAVY    = "1E2761";
const ICE     = "CADCFC";
const WHITE   = "FFFFFF";
const SLATE   = "1E293B";
const MUTED   = "64748B";
const LIGHT   = "F8FAFC";
const ACCENT  = "0EA5E9";
const SUCCESS = "10B981";
const WARN    = "F59E0B";
const CARD_BG = "FFFFFF";

// ─── Helpers ──────────────────────────────────────────────────────────────────
const makeShadow = () => ({
  type: "outer", blur: 8, offset: 3, angle: 135,
  color: "000000", opacity: 0.12
});

// ─── Presentation ────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout  = "LAYOUT_16x9";
pres.title   = "KnowSelf: Agentic Knowledgeable Self-Awareness for LLM-Based Agents";
pres.author  = "KnowSelf Research";

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: NAVY };

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08, fill: { color: ACCENT }
  });

  sl.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 0.5, y: 0.4, w: 2.2, h: 0.36,
    fill: { color: ACCENT, transparency: 20 }, rectRadius: 0.06
  });
  sl.addText("arXiv:2504.03553", {
    x: 0.5, y: 0.4, w: 2.2, h: 0.36,
    fontSize: 10, color: ICE, align: "center", valign: "middle",
    fontFace: "Consolas", margin: 0
  });

  sl.addText("KnowSelf", {
    x: 0.5, y: 1.2, w: 9, h: 1.0,
    fontSize: 52, fontFace: "Georgia", bold: true,
    color: WHITE, align: "left", margin: 0
  });

  sl.addText("Teaching LLM Agents When to Think, Reflect, or Seek Knowledge", {
    x: 0.5, y: 2.2, w: 8, h: 0.7,
    fontSize: 20, fontFace: "Calibri",
    color: ICE, align: "left", margin: 0
  });

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.05, w: 3.5, h: 0.04, fill: { color: ACCENT }
  });

  sl.addText(
    "Enabling agents to autonomously regulate knowledge utilization\nthrough situational self-awareness",
    {
      x: 0.5, y: 3.25, w: 8, h: 0.8,
      fontSize: 14, fontFace: "Calibri", italic: true,
      color: ICE, align: "left", margin: 0
    }
  );

  sl.addText("ML Researchers & Graduate Students  ·  LLM Agents & Planning Systems", {
    x: 0.5, y: 5.0, w: 9, h: 0.35,
    fontSize: 10, fontFace: "Consolas",
    color: MUTED, align: "left", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Problem: Flood Irrigation
// ══════════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: LIGHT };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: NAVY } });
  sl.addText("Current Agent Training Uses 'Flood Irrigation'", {
    x: 0.5, y: 0.12, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Georgia", bold: true,
    color: WHITE, align: "left", valign: "middle", margin: 0
  });
  sl.addText("Indiscriminate Knowledge Injection Hurts Efficiency", {
    x: 0.5, y: 0.55, w: 9, h: 0.25,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: ICE, align: "left", margin: 0
  });

  sl.addText("Three dominant paradigms — all blindly apply gold trajectories / feedback / knowledge at every step", {
    x: 0.5, y: 0.95, w: 9.0, h: 0.4,
    fontSize: 12, fontFace: "Calibri", color: MUTED, align: "left", margin: 0
  });

  const paradigms = [
    {
      label: "Trajectory Imitation",
      methods: "ReAct, vanilla fine-tuning",
      color: "3B82F6",
      desc: "Memorizes gold action sequences without situational judgment"
    },
    {
      label: "Trial & Error Refinement",
      methods: "Reflexion, self-correction loops",
      color: "8B5CF6",
      desc: "Repeats failed attempts — costly, no external knowledge integration"
    },
    {
      label: "Knowledge-Augmented",
      methods: "KnowAgent, WKM",
      color: WARN,
      desc: "Retrieves external KB at every step regardless of actual need"
    }
  ];

  paradigms.forEach((p, i) => {
    const x = 0.5 + i * 3.05;
    sl.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.45, w: 2.9, h: 2.0,
      fill: { color: CARD_BG }, shadow: makeShadow()
    });
    sl.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.45, w: 2.9, h: 0.08, fill: { color: p.color }
    });
    sl.addText(p.label, {
      x: x + 0.15, y: 1.6, w: 2.6, h: 0.34,
      fontSize: 12, fontFace: "Calibri", bold: true,
      color: SLATE, align: "left", margin: 0
    });
    sl.addText(p.methods, {
      x: x + 0.15, y: 1.94, w: 2.6, h: 0.26,
      fontSize: 9, fontFace: "Consolas",
      color: MUTED, align: "left", margin: 0
    });
    sl.addText(p.desc, {
      x: x + 0.15, y: 2.24, w: 2.6, h: 0.65,
      fontSize: 10, fontFace: "Calibri",
      color: SLATE, align: "left", margin: 0
    });
  });

  sl.addText("↓", {
    x: 4.5, y: 3.45, w: 1, h: 0.38,
    fontSize: 20, color: MUTED, align: "center", margin: 0
  });

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.88, w: 9.0, h: 0.6,
    fill: { color: NAVY }
  });
  sl.addText("Result: Fragile planning on novel inputs  ·  Excessive inference cost  ·  Pattern collapse", {
    x: 0.5, y: 3.88, w: 9.0, h: 0.6,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: WHITE, align: "center", valign: "middle", margin: 0
  });

  sl.addText("Humans possess metacognitive self-awareness — KnowSelf brings this to LLM agents.", {
    x: 0.5, y: 4.6, w: 9.0, h: 0.32,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: MUTED, align: "center", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Three Thinking Modes (Decision Tree)
// ══════════════════════════════════════════════════════════════════════════════
{
  const sl = pres.addSlide();
  sl.background = { color: LIGHT };

  sl.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: NAVY } });
  sl.addText("Three Situational Modes of Thinking", {
    x: 0.5, y: 0.12, w: 9, h: 0.6,
    fontSize: 22, fontFace: "Georgia", bold: true,
    color: WHITE, align: "left", valign: "middle", margin: 0
  });
  sl.addText("Fast  ·  Slow  ·  Knowledgeable", {
    x: 0.5, y: 0.55, w: 9, h: 0.25,
    fontSize: 11, fontFace: "Calibri", italic: true,
    color: ICE, align: "left", margin: 0
  });

  // Root node
  sl.addShape(pres.shapes.OVAL, {
    x: 4.2, y: 1.05, w: 1.6, h: 0.65,
    fill: { color: NAVY }, shadow: makeShadow()
  });
  sl.addText("Agent\nDecision?", {
    x: 4.2, y: 1.05, w: 1.6, h: 0.65,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: WHITE, align: "center", valign: "middle", margin: 0
  });

  // First question
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 3.55, y: 1.9, w: 2.9, h: 0.5,
    fill: { color: ACCENT }, shadow: makeShadow()
  });
  sl.addText("Can produce correct action?", {
    x: 3.55, y: 1.9, w: 2.9, h: 0.5,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: WHITE, align: "center", valign: "middle", margin: 0
  });

  // YES branch (left) → Fast Thinking
  sl.addShape(pres.shapes.LINE, {
    x: 3.55, y: 2.4, w: -1.1, h: 0.55,
    line: { color: SUCCESS, width: 2 }
  });
  sl.addText("YES", {
    x: 2.3, y: 2.42, w: 0.5, h: 0.22,
    fontSize: 9, fontFace: "Calibri", bold: true,
    color: SUCCESS, align: "center", margin: 0
  });

  // Fast Thinking card
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 2.95, w: 2.6, h: 1.45,
    fill: { color: CARD_BG }, shadow: makeShadow()
  });
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 2.95, w: 2.6, h: 0.06, fill: { color: SUCCESS }
  });
  sl.addText("Fast Thinking", {
    x: 0.55, y: 3.08, w: 2.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: SLATE, align: "left", margin: 0
  });
  sl.addText([
    { text: "Direct correct action", options: { breakLine: true } },
    { text: "No deliberation needed", options: { breakLine: true } },
    { text: "Token: [FAST]", options: {} }
  ], {
    x: 0.55, y: 3.4, w: 2.3, h: 0.85,
    fontSize: 9, fontFace: "Calibri", color: MUTED, align: "left", margin: 0
  });

  // NO branch (right) → Second question
  sl.addShape(pres.shapes.LINE, {
    x: 6.45, y: 2.4, w: 1.15, h: 0.55,
    line: { color: WARN, width: 2 }
  });
  sl.addText("NO", {
    x: 7.25, y: 2.42, w: 0.5, h: 0.22,
    fontSize: 9, fontFace: "Calibri", bold: true,
    color: WARN, align: "center", margin: 0
  });

  // Second question
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 7.1, y: 2.95, w: 2.5, h: 0.5,
    fill: { color: ACCENT }, shadow: makeShadow()
  });
  sl.addText("Reflection corrects?", {
    x: 7.1, y: 2.95, w: 2.5, h: 0.5,
    fontSize: 11, fontFace: "Calibri", bold: true,
    color: WHITE, align: "center", valign: "middle", margin: 0
  });

  // YES → Slow Thinking (down-left)
  sl.addShape(pres.shapes.LINE, {
    x: 7.1, y: 3.45, w: -1.35, h: 0.55,
    line: { color: SUCCESS, width: 2 }
  });
  sl.addText("YES", {
    x: 5.6, y: 3.48, w: 0.5, h: 0.22,
    fontSize: 9, fontFace: "Calibri", bold: true,
    color: SUCCESS, align: "center", margin: 0
  });

  sl.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 4.0, w: 2.6, h: 1.45,
    fill: { color: CARD_BG }, shadow: makeShadow()
  });
  sl.addShape(pres.shapes.RECTANGLE, {
    x: 3.5, y: 4.0, w: 2.6, h: 0.06, fill: { color: "8B5CF6" }
  });
  sl.addText("Slow Thinking", {
    x: 3.65, y: 4.13, w: 2.3, h: 0.3,
    fontSize: 12, fontFace: "Calibri", bold: true,
    color: SLATE, align: "left", margin: 0
  });
  sl.addText([
    { text: "Incorrect → self-correct", options: { breakLine: true } },
